CREATE TABLE locking_records (
    record_id integer NOT NULL,
    position integer NOT NULL,
    group_id integer NOT NULL,
    label text NOT NULL,
    kind integer NOT NULL,
    tag text NOT NULL,
    PRIMARY KEY (record_id, position)
);
